function cleanCart(){const q0=cart.reduce((a,c)=>a+c.q,0);cart=cart.map(c=>{const p=products.find(x=>x.id==c.id);return p&&act(p)&&p.stock>0?{id:c.id,q:Math.min(c.q,p.stock)}:null}).filter(c=>c&&c.q>0);if(cart.reduce((a,c)=>a+c.q,0)!==q0){save('cart',cart);return true}return false}
const itemsText=o=>[...(o.bundles||[]).map(b=>'🎁 '+esc(b.name)+(b.sets>1?' ×'+b.sets:'')+' ('+b.items.map(i=>esc(i.name)+(i.q>1?' ×'+i.q:'')).join(', ')+')'),...o.items.filter(i=>i.q-(i.bq||0)>0).map(i=>esc(i.name)+' × '+(i.q-(i.bq||0)))].join(', ');
