const promoOf=p=>{let d=0,m=null;promos.filter(isLive).forEach(x=>{if(x.scope=='all'||(x.scope=='cat'&&x.cat==p.cat)||(x.scope=='prod'&&(x.ids||[]).includes(p.id))){const v=x.type=='pct'?r2(p.price*x.val/100):Math.min(p.price,x.val);if(v>d){d=v;m=x}}});return{d,m,price:r2(p.price-d)}};
const bfull=b=>r2(b.items.reduce((a,i)=>{const p=products.find(x=>x.id==i.id);return a+(p?p.price*i.q:0)},0));
const bdisc=b=>{const f=bfull(b);return b.type=='pct'?r2(f*b.val/100):Math.min(b.val,f)};
const bOk=b=>b.items.length&&b.items.every(i=>{const p=products.find(x=>x.id==i.id);return p&&act(p)&&p.stock>=i.q});
const liveBundles=()=>bundles.filter(b=>isLive(b)&&bOk(b));
const scopeText=m=>m.scope=='all'?'everything in the shop':m.scope=='cat'?'in '+m.cat:(m.ids||[]).map(i=>products.find(p=>p.id==i)?.name).filter(Boolean).slice(0,3).join(', ')+((m.ids||[]).length>3?' and more':'');
function pricing(){const av={};cart.forEach(c=>av[c.id]=c.q);let list=0,bd=0,pd=0;const bl=[],bu={};
 cart.forEach(c=>{const p=products.find(x=>x.id==c.id);if(p)list+=p.price*c.q});
 bundles.filter(b=>isLive(b)&&b.items.length&&b.items.every(i=>{const p=products.find(x=>x.id==i.id);return p&&act(p)})).map(b=>({b,d:bdisc(b)})).sort((x,y)=>y.d-x.d).forEach(({b,d})=>{const n=Math.min(...b.items.map(i=>Math.floor((av[i.id]||0)/i.q)));if(n>0){b.items.forEach(i=>{av[i.id]-=i.q*n;bu[i.id]=(bu[i.id]||0)+i.q*n});bd+=d*n;bl.push({b,n,d:r2(d*n)})}});
 Object.keys(av).forEach(id=>{const p=products.find(x=>x.id==id);if(p&&av[id]>0)pd+=promoOf(p).d*av[id]});
 return{list:r2(list),bd:r2(bd),pd:r2(pd),bl,bu,total:r2(list-bd-pd)}}
const need=(b,onlyMissing)=>b.items.map(i=>({id:i.id,q:i.q-(onlyMissing?(cart.find(c=>c.id==i.id)?.q||0):0)})).filter(x=>x.q>0);
