const bundleCard=b=>{const its=b.items.map(i=>({p:products.find(x=>x.id==i.id),q:i.q})).filter(x=>x.p),f=bfull(b),d=bdisc(b);return `<div class="panel bundle"><div class="row"><h3>🎁 ${esc(b.name)}</h3><span class="tag">Save ${money(d)}</span></div>${b.tag?`<small>${esc(b.tag)}</small>`:''}<div style="margin:10px 0">${its.map(x=>`<a href="#/product/${x.p.id}">${thumb(x.p)}</a> ${x.q>1?'×'+x.q+' ':''}${esc(x.p.name)}`).join(' + ')}</div><div class="row"><span><s class="was">${money(f)}</s> <b class="price">${money(r2(f-d))}</b> <small>until ${b.e}</small></span><button data-act="addb" data-v="${b.id}">Add bundle</button></div></div>`};
